{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "type": "object",
  "title": "Arise Config",
  "description": "Arise 主配置結構 / Arise main configuration schema",
  "additionalProperties": false,
  "properties": {
    "$schema": {
      "type": "string",
      "title": "Schema",
      "description": "JSON Schema URI / JSON Schema URI"
    },
    "disabled_shadows": {
      "type": "array",
      "title": "Disabled Shadows",
      "description": "要停用的 Shadow Agents 列表 / List of Shadow Agents to disable",
      "items": {
        "type": "string",
        "title": "Shadow Agent Name",
        "description": "Shadow Agent 名稱 / Shadow Agent name",
        "enum": [
          "monarch",
          "beru",
          "igris",
          "bellion",
          "tusk",
          "tank",
          "shadow-sovereign",
          "esil-radiru"
        ]
      }
    },
    "disabled_tools": {
      "type": "array",
      "title": "Disabled Tools",
      "description": "要停用的工具列表 / List of tools to disable",
      "items": {
        "type": "string",
        "enum": [
          "arise_summon",
          "arise_background",
          "arise_background_output",
          "arise_background_status",
          "arise_background_cancel",
          "arise_list_models",
          "arise_continue",
          "arise_debug",
          "arise_git_summary",
          "arise_collaborate"
        ]
      }
    },
    "disabled_hooks": {
      "type": "array",
      "title": "Disabled Hooks",
      "description": "要停用的 Hook 列表 / List of hooks to disable",
      "items": {
        "type": "string",
        "title": "Hook Name",
        "description": "生命週期 Hook 名稱 / Lifecycle hook name",
        "enum": [
          "arise-banner",
          "output-shaper",
          "compaction-preserver",
          "todo-enforcer"
        ]
      }
    },
    "show_banner": {
      "type": "boolean",
      "title": "Show Banner",
      "description": "是否顯示歡迎橫幅 / Show welcome banner",
      "default": true
    },
    "banner_every_session": {
      "type": "boolean",
      "title": "Banner Every Session",
      "description": "每個工作階段都顯示橫幅 / Show banner every session",
      "default": false
    },
    "agents": {
      "type": "object",
      "title": "Agents",
      "description": "各代理的覆寫設定 / Per-agent override settings",
      "additionalProperties": {
        "type": "object",
        "title": "Agent Override",
        "description": "代理覆寫設定 / Agent override settings",
        "additionalProperties": false,
        "properties": {
          "model": {
            "type": "string",
            "title": "Model",
            "description": "要使用的模型名稱 / Model name to use"
          },
          "disabled": {
            "type": "boolean",
            "title": "Disabled",
            "description": "是否停用此代理 / Whether to disable this agent"
          },
          "system_prompt_addon": {
            "type": "string",
            "title": "System Prompt Addon",
            "description": "系統提示補充內容 / System prompt supplement content"
          },
          "poll_interval": {
            "type": "number",
            "title": "Poll Interval",
            "description": "輪詢間隔（毫秒）/ Polling interval in milliseconds",
            "default": 2000
          },
          "retry_delay_increment": {
            "type": "number",
            "title": "Retry Delay Increment",
            "description": "重試延遲遞增量（毫秒）/ Retry delay increment in milliseconds",
            "default": 5000
          },
          "retry_delay_max": {
            "type": "number",
            "title": "Retry Delay Max",
            "description": "重試延遲最大值（毫秒）/ Maximum retry delay in milliseconds",
            "default": 60000
          },
          "auto_resume": {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "enabled",
              "max_retries",
              "retry_delay",
              "on_error",
              "target",
              "prompts",
              "safety_prompt"
            ],
            "properties": {
              "enabled": {
                "type": "boolean",
                "title": "Enabled",
                "description": "是否啟用自動繼續任務 / Enable auto resume"
              },
              "max_retries": {
                "type": "number",
                "title": "Max Retries",
                "description": "最大重試次數 / Maximum retry count"
              },
              "retry_delay": {
                "type": "number",
                "title": "Retry Delay",
                "description": "重試延遲（毫秒）/ Retry delay in milliseconds"
              },
              "on_error": {
                "type": "string",
                "title": "On Error",
                "description": "錯誤時的行為：ignore=忽略、retry=重試、notify=通知 / Behavior on error: ignore=ignore, retry=retry, notify=notify",
                "enum": [
                  "ignore",
                  "retry",
                  "notify"
                ]
              },
              "target": {
                "type": "string",
                "title": "Target",
                "description": "目標任務類型：background=背景任務、all=所有任務 / Target task type: background=background tasks, all=all tasks",
                "enum": [
                  "background",
                  "all"
                ]
              },
              "prompts": {
                "type": "object",
                "title": "Prompts",
                "description": "自訂提示訊息 / Custom prompts",
                "additionalProperties": false,
                "properties": {
                  "retry": {
                    "type": "string",
                    "title": "Retry Prompt",
                    "description": "首次重試時的提示 / Prompt for first retry"
                  },
                  "final": {
                    "type": "string",
                    "title": "Final Prompt",
                    "description": "最終重試時的提示 / Prompt for final retry"
                  },
                  "custom": {
                    "type": "array",
                    "title": "Custom Prompts",
                    "description": "自定義提示陣列，按順序使用 / Custom prompt array, used in order",
                    "items": {
                      "type": "string"
                    }
                  }
                }
              },
              "safety_prompt": {
                "type": "string",
                "title": "Safety Prompt",
                "description": "自動繼續任務前发送的安全检查提示 / Safety check prompt before auto resume"
              }
            }
          }
        }
      },
      "required": [
        "monarch",
        "beru",
        "igris",
        "bellion",
        "tusk",
        "tank",
        "shadow-sovereign",
        "esil-radiru"
      ],
      "propertyNames": {
        "type": "string",
        "title": "Shadow Agent Name",
        "description": "Shadow Agent 名稱 / Shadow Agent name",
        "enum": [
          "monarch",
          "beru",
          "igris",
          "bellion",
          "tusk",
          "tank",
          "shadow-sovereign",
          "esil-radiru"
        ]
      }
    },
    "output_shaping": {
      "type": "object",
      "title": "Output Shaping",
      "description": "輸出截斷設定 / Output truncation settings",
      "additionalProperties": false,
      "required": [
        "max_chars",
        "preserve_errors"
      ],
      "properties": {
        "max_chars": {
          "type": "number",
          "title": "Max Chars",
          "description": "最大輸出字元數 / Maximum output characters",
          "default": 12000
        },
        "preserve_errors": {
          "type": "boolean",
          "title": "Preserve Errors",
          "description": "是否保留錯誤輸出 / Preserve error output",
          "default": true
        }
      }
    },
    "compaction": {
      "type": "object",
      "title": "Compaction",
      "description": "對話壓縮設定 / Conversation compaction settings",
      "additionalProperties": false,
      "required": [
        "threshold_percent",
        "preserve_todos"
      ],
      "properties": {
        "threshold_percent": {
          "type": "number",
          "title": "Threshold Percent",
          "description": "觸發壓縮的閾值百分比（50-95）/ Compaction threshold percent (50-95)",
          "default": 80,
          "minimum": 50,
          "maximum": 95
        },
        "preserve_todos": {
          "type": "boolean",
          "title": "Preserve TODOs",
          "description": "保留 TODO 項目 / Preserve TODO items",
          "default": true
        }
      }
    },
    "background": {
      "type": "object",
      "title": "Background",
      "description": "背景任務設定 / Background task settings",
      "additionalProperties": false,
      "required": [
        "poll_interval",
        "retry_delay_increment",
        "retry_delay_max"
      ],
      "properties": {
        "poll_interval": {
          "type": "number",
          "title": "Poll Interval",
          "description": "輪詢間隔（毫秒）/ Polling interval in milliseconds",
          "default": 2000
        },
        "retry_delay_increment": {
          "type": "number",
          "title": "Retry Delay Increment",
          "description": "重試延遲遞增量（毫秒）/ Retry delay increment in milliseconds",
          "default": 5000
        },
        "retry_delay_max": {
          "type": "number",
          "title": "Retry Delay Max",
          "description": "重試延遲最大值（毫秒）/ Maximum retry delay in milliseconds",
          "default": 60000
        },
        "auto_resume": {
          "type": "object",
          "title": "Auto Resume",
          "description": "自動繼續任務設定 / Auto resume settings",
          "additionalProperties": false,
          "required": [
            "enabled",
            "on_error",
            "target"
          ],
          "properties": {
            "enabled": {
              "type": "boolean",
              "title": "Enabled",
              "description": "是否啟用自動繼續任務 / Enable auto resume",
              "default": false
            },
            "max_retries": {
              "type": "number",
              "title": "Max Retries",
              "description": "最大重試次數 / Maximum retry count",
              "default": 3
            },
            "retry_delay": {
              "type": "number",
              "title": "Retry Delay",
              "description": "重試延遲（毫秒）/ Retry delay in milliseconds",
              "default": 5000
            },
            "on_error": {
              "type": "string",
              "title": "On Error",
              "description": "錯誤時的行為：ignore=忽略、retry=重試、notify=通知 / Behavior on error: ignore=ignore, retry=retry, notify=notify",
              "default": "ignore",
              "enum": [
                "ignore",
                "retry",
                "notify"
              ]
            },
            "target": {
              "type": "string",
              "title": "Target",
              "description": "目標任務類型：background=背景任務、all=所有任務 / Target task type: background=background tasks, all=all tasks",
              "default": "background",
              "enum": [
                "background",
                "all"
              ]
            },
            "prompts": {
              "type": "object",
              "title": "Prompts",
              "description": "自訂提示訊息 / Custom prompts",
              "additionalProperties": false,
              "properties": {
                "retry": {
                  "type": "string",
                  "title": "Retry Prompt",
                  "description": "首次重試時的提示 / Prompt for first retry"
                },
                "final": {
                  "type": "string",
                  "title": "Final Prompt",
                  "description": "最終重試時的提示 / Prompt for final retry"
                },
                "custom": {
                  "type": "array",
                  "title": "Custom Prompts",
                  "description": "自定義提示陣列，按順序使用 / Custom prompt array, used in order",
                  "items": {
                    "type": "string"
                  }
                }
              }
            },
            "safety_prompt": {
              "type": "string",
              "title": "Safety Prompt",
              "description": "自動繼續任務前发送的安全检查提示 / Safety check prompt before auto resume",
              "default": "請依序檢查：\n1. 若後續任務明確可行，繼續執行\n2. 若存在潛在風險（如破壞性變更、資料遺失、安全疑慮、或將更動專案外檔案），請先停止並說明風險，請求用戶確認\n3. 若需求模糊或資訊不足，請停止並說明疑點，請求用戶澄清\n4. 若非用戶明確要求撤銷更改或刪除檔案，請先詢問用戶，獲得許可後才執行\n\n**若任務已完成，請複查並總結結果後結束**\n\nCheck in order:\n1. If the next step is clear and actionable, proceed.\n2. If potential risks exist (e.g., destructive changes, data loss, security concerns, or modifying files outside the project), stop, explain the risks, and request confirmation.\n3. If requirements are ambiguous or information is insufficient, stop, state the uncertainty, and request clarification.\n4. Unless the user explicitly requests to revert changes or delete files, always ask for permission first and only proceed after obtaining user consent.\n\n**If the task is complete, review and summarize the results, then end.**"
            }
          }
        }
      }
    },
    "collaborate": {
      "type": "object",
      "title": "Collaborate",
      "description": "協作任務設定 / Collaboration task settings",
      "additionalProperties": false,
      "properties": {
        "allowed_modes": {
          "type": "array",
          "title": "Allowed Modes",
          "description": "允許的模式列表，若設定則只允許這些模式 / Allowed modes, if set only these modes are allowed",
          "items": {
            "type": "string",
            "enum": [
              "planning",
              "parallel",
              "chain"
            ]
          }
        },
        "denied_modes": {
          "type": "array",
          "title": "Denied Modes",
          "description": "禁止的模式列表，優先於 allowed_modes / Denied modes, takes precedence over allowed_modes",
          "items": {
            "type": "string",
            "enum": [
              "planning",
              "parallel",
              "chain"
            ]
          }
        },
        "total_rounds": {
          "type": "integer",
          "title": "Total Rounds",
          "description": "預設總回合數（預設 8）/ Default total rounds (default 8)",
          "minimum": 1,
          "maximum": 9007199254740991
        },
        "total_rounds_max": {
          "type": "integer",
          "title": "Total Rounds Max",
          "description": "總回合數最大上限（預設 15）/ Total rounds maximum limit (default 15)",
          "minimum": 1,
          "maximum": 9007199254740991
        },
        "per_agent_rounds": {
          "type": "integer",
          "title": "Per Agent Rounds",
          "description": "預設每個 agent 回合數 / Default per-agent rounds",
          "exclusiveMinimum": 0,
          "maximum": 9007199254740991
        },
        "max_concurrent": {
          "type": "integer",
          "title": "Max Concurrent",
          "description": "預設最大並行數（最大 5）/ Default max concurrent (max 5)",
          "minimum": 1,
          "maximum": 9007199254740991
        },
        "round_timeout_ms": {
          "type": "integer",
          "title": "Round Timeout",
          "description": "預設回合超時（毫秒）/ Default round timeout (ms)",
          "exclusiveMinimum": 0,
          "maximum": 9007199254740991
        },
        "round_timeout_ms_max": {
          "type": "integer",
          "title": "Round Timeout Max",
          "description": "回合超時最大上限（毫秒）/ Round timeout maximum limit (ms)",
          "exclusiveMinimum": 0,
          "maximum": 9007199254740991
        }
      }
    },
    "debug": {
      "type": "object",
      "title": "Debug",
      "description": "除錯設定 / Debug settings",
      "additionalProperties": false,
      "required": [
        "enabled",
        "level"
      ],
      "properties": {
        "enabled": {
          "type": "boolean",
          "title": "Enabled",
          "description": "是否啟用除錯模式 / Enable debug mode",
          "default": false
        },
        "level": {
          "type": "string",
          "title": "Level",
          "description": "日誌級別：error、warn、info、debug / Log level: error, warn, info, debug",
          "default": "warn",
          "enum": [
            "error",
            "warn",
            "info",
            "debug"
          ]
        }
      }
    }
  }
}

